const crypto = require('crypto');
const SECRET = $('Get Secret').first().json.value;
const hmac = (msg) => crypto.createHmac('sha256', SECRET).update(msg).digest('hex').slice(0, 32);
const base = 'https://designprodigy.app.n8n.cloud/webhook/action-approval';
const msgs = $('Find Digest Replies').all().map(i => i.json);
const b64 = (d) => { try { return Buffer.from(String(d).replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8'); } catch (e) { return ''; } };
function textFrom(p) {
  if (!p) return '';
  if (p.mimeType === 'text/plain' && p.body && p.body.data) return b64(p.body.data);
  if (p.mimeType === 'text/html' && p.body && p.body.data) return b64(p.body.data).replace(/<[^>]+>/g, ' ');
  if (Array.isArray(p.parts)) return p.parts.map(textFrom).join('\n');
  return '';
}
const header = (m, name) => { const h = (m.payload && m.payload.headers) || []; const f = h.find(x => (x.name || '').toLowerCase() === name); return f ? f.value : ''; };
const out = [];
for (const m of msgs) {
  const subject = header(m, 'subject');
  if (!/^\s*re:/i.test(subject)) continue; // only replies, never the digest itself
  const from = header(m, 'from');
  const fromEmail = (from.match(/<([^>]+)>/) || [null, from.trim()])[1];
  const full = textFrom(m.payload) || m.snippet || '';
  // ordinal -> action id map, from the quoted digest links (in order of appearance)
  const ids = [];
  const seen = new Set();
  const re = /[?&](?:action_)?id=(\d+)/g;
  let mt;
  while ((mt = re.exec(full)) !== null) { if (!seen.has(mt[1])) { seen.add(mt[1]); ids.push(mt[1]); } }
  // commands from the fresh (non-quoted) part: cut at first quote marker
  const fresh = full.split(/\r?\n(?:>|On .{5,80} wrote:)/)[0];
  const cmds = [];
  const cmdRe = /\b(done|did|ok|approve|approved|skip|reject|no)\b[:\s]+((?:\d+[\s,and]*)+|all)/gi;
  let c;
  while ((c = cmdRe.exec(fresh)) !== null) {
    const verb = /^(skip|reject|no)$/i.test(c[1]) ? 'reject' : 'approve';
    const nums = /all/i.test(c[2]) ? ids.map((_, i) => i + 1) : (c[2].match(/\d+/g) || []).map(Number);
    for (const n of nums) cmds.push({ verb, ordinal: n });
  }
  const applied = [];
  const invalid = [];
  for (const { verb, ordinal } of cmds) {
    const id = ids[ordinal - 1];
    if (!id) { invalid.push(ordinal); continue; }
    const sig = hmac(`action:${id}:${verb}`);
    const url = `${base}?id=${id}&action=${verb}${verb === 'reject' ? '&reason=skipped_via_digest_reply' : '&src=auto'}&sig=${sig}`;
    out.push({ json: { kind: 'call', url } });
    applied.push(`#${ordinal} → ${verb === 'approve' ? 'done' : 'skipped'}`);
  }
  let summary;
  if (!cmds.length) summary = `I couldn't find any commands in your reply. Use lines like:\n  done 1 3\n  skip 2\nor "done all". Numbers match the touch numbers in the digest.`;
  else summary = `Logged from your reply: ${applied.join(', ')}${invalid.length ? `. Couldn't match number(s): ${invalid.join(', ')}` : ''}.`;
  out.push({ json: { kind: 'confirm', messageId: m.id, sendTo: fromEmail, summary, subject } });
}
return out;
